import{_ as e,o,c as t,a3 as a}from"./chunks/framework.B8xISX-C.js";const b=JSON.parse('{"title":"buildings","description":"","frontmatter":{},"headers":[],"relativePath":"reference/buildings.md","filePath":"reference/buildings.md"}'),i={name:"reference/buildings.md"};function l(c,d,s,n,u,r){return o(),t("div",null,[...d[0]||(d[0]=[a('<h1 id="buildings" tabindex="-1">buildings <a class="header-anchor" href="#buildings" aria-label="Permalink to &quot;buildings&quot;">​</a></h1><p>A colony building. Its behaviour comes from its <code>effects</code> (economy, research and defence effects); a building without effects does nothing unless a rule names it. Its <code>autobuild</code> block says how the computer players weigh it.</p><p>A mod adds records in <code>records/buildings/&lt;file&gt;.json</code> (<code>{ &quot;$schema&quot;: &quot;carina-records/1&quot;, &quot;catalog&quot;: &quot;buildings&quot;, &quot;records&quot;: [...] }</code>) and changes base records with patch rows on catalog <code>buildings</code>. Schema: <code>schemas/records/buildings.schema.json</code>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>A mod record leaves out <code>id</code> and <code>prov</code>: the game assigns ids, and <code>prov</code> is the project&#39;s own provenance.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><span id="f-key" class="field-name"><code>key</code></span><a class="field-link" href="#f-key" aria-label="Link to key">#</a></td><td><code>&lt;namespace&gt;.&lt;snake_case&gt;</code>: your package id with <code>-</code> read as <code>_</code>, then a name</td><td>yes</td><td></td></tr><tr><td><span id="f-application" class="field-name"><code>application</code></span><a class="field-link" href="#f-application" aria-label="Link to application">#</a></td><td>key of a record in <code>applications</code></td><td>yes</td><td>the key of the application that unlocks it (null: never unlocked by research)</td></tr><tr><td><span id="f-cost" class="field-name"><code>cost</code></span><a class="field-link" href="#f-cost" aria-label="Link to cost">#</a></td><td>integer &gt;= 0</td><td>yes</td><td></td></tr><tr><td><span id="f-upkeep" class="field-name"><code>upkeep</code></span><a class="field-link" href="#f-upkeep" aria-label="Link to upkeep">#</a></td><td>integer &gt;= 0</td><td>yes</td><td>BC per turn</td></tr><tr><td><span id="f-buildable" class="field-name"><code>buildable</code></span><a class="field-link" href="#f-buildable" aria-label="Link to buildable">#</a></td><td>true or false</td><td>yes</td><td>players can put it in the build queue</td></tr><tr><td><span id="f-hull" class="field-name"><code>hull</code></span><a class="field-link" href="#f-hull" aria-label="Link to hull">#</a></td><td>key of a record in <code>hulls</code>, or null</td><td>yes</td><td>for orbital bases, the key of their hull</td></tr><tr><td><span id="f-nameKey" class="field-name"><code>nameKey</code></span><a class="field-link" href="#f-nameKey" aria-label="Link to nameKey">#</a></td><td>text key</td><td>yes</td><td></td></tr><tr><td><span id="f-autobuild" class="field-name"><code>autobuild</code></span><a class="field-link" href="#f-autobuild" aria-label="Link to autobuild">#</a></td><td>one of 17 forms told apart by <code>kind</code> (fields below)</td><td>yes</td><td>how the empire AI and Auto Build weigh it</td></tr><tr><td><span id="f-autobuild.kind" class="field-name"><code>autobuild.kind</code></span><a class="field-link" href="#f-autobuild.kind" aria-label="Link to autobuild.kind">#</a></td><td>one of <code>flat</code>, <code>capitol</code>, <code>research</code>, <code>industry</code>, <code>pollution</code>, <code>cloning</code>, <code>ecology</code>, <code>foodBoost</code>, <code>farm</code>, <code>city</code>, <code>gravity</code>, <code>trade</code>, <code>salvage</code>, <code>academy</code>, <code>terraform</code>, <code>garrison</code>, <code>defence</code></td><td>yes</td><td>picks the form; the other fields follow it</td></tr><tr><td><span id="f-autobuild.w" class="field-name"><code>autobuild.w</code></span><a class="field-link" href="#f-autobuild.w" aria-label="Link to autobuild.w">#</a></td><td>integer 0..1000</td><td>no</td><td>in <code>flat</code>, <code>capitol</code>, <code>city</code></td></tr><tr><td><span id="f-autobuild.base" class="field-name"><code>autobuild.base</code></span><a class="field-link" href="#f-autobuild.base" aria-label="Link to autobuild.base">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>research</code>, <code>industry</code>, <code>ecology</code></td></tr><tr><td><span id="f-autobuild.tech" class="field-name"><code>autobuild.tech</code></span><a class="field-link" href="#f-autobuild.tech" aria-label="Link to autobuild.tech">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>research</code></td></tr><tr><td><span id="f-autobuild.pop" class="field-name"><code>autobuild.pop</code></span><a class="field-link" href="#f-autobuild.pop" aria-label="Link to autobuild.pop">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>industry</code>, <code>salvage</code></td></tr><tr><td><span id="f-autobuild.ind" class="field-name"><code>autobuild.ind</code></span><a class="field-link" href="#f-autobuild.ind" aria-label="Link to autobuild.ind">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>industry</code></td></tr><tr><td><span id="f-autobuild.skipFocus" class="field-name"><code>autobuild.skipFocus</code></span><a class="field-link" href="#f-autobuild.skipFocus" aria-label="Link to autobuild.skipFocus">#</a></td><td>true or false</td><td>no</td><td>in <code>pollution</code>, <code>ecology</code>, <code>foodBoost</code>, <code>farm</code></td></tr><tr><td><span id="f-autobuild.treasuryDiv" class="field-name"><code>autobuild.treasuryDiv</code></span><a class="field-link" href="#f-autobuild.treasuryDiv" aria-label="Link to autobuild.treasuryDiv">#</a></td><td>integer &gt;= 1</td><td>no</td><td>in <code>cloning</code>, <code>ecology</code>, <code>garrison</code>, <code>defence</code></td></tr><tr><td><span id="f-autobuild.eco" class="field-name"><code>autobuild.eco</code></span><a class="field-link" href="#f-autobuild.eco" aria-label="Link to autobuild.eco">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>ecology</code>, <code>foodBoost</code>, <code>farm</code>, <code>gravity</code>, <code>terraform</code></td></tr><tr><td><span id="f-autobuild.surplus" class="field-name"><code>autobuild.surplus</code></span><a class="field-link" href="#f-autobuild.surplus" aria-label="Link to autobuild.surplus">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>foodBoost</code></td></tr><tr><td><span id="f-autobuild.deficit" class="field-name"><code>autobuild.deficit</code></span><a class="field-link" href="#f-autobuild.deficit" aria-label="Link to autobuild.deficit">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>foodBoost</code></td></tr><tr><td><span id="f-autobuild.needsFarming" class="field-name"><code>autobuild.needsFarming</code></span><a class="field-link" href="#f-autobuild.needsFarming" aria-label="Link to autobuild.needsFarming">#</a></td><td>true or false</td><td>no</td><td>in <code>foodBoost</code></td></tr><tr><td><span id="f-autobuild.byFood" class="field-name"><code>autobuild.byFood</code></span><a class="field-link" href="#f-autobuild.byFood" aria-label="Link to autobuild.byFood">#</a></td><td>[integer &gt;= 0, integer &gt;= 0, integer &gt;= 0, integer &gt;= 0]</td><td>no</td><td>in <code>farm</code></td></tr><tr><td><span id="f-autobuild.rows" class="field-name"><code>autobuild.rows</code></span><a class="field-link" href="#f-autobuild.rows" aria-label="Link to autobuild.rows">#</a></td><td>list of object (fields below)</td><td>no</td><td>in <code>gravity</code></td></tr><tr><td><span id="f-autobuild.popAbove" class="field-name"><code>autobuild.popAbove</code></span><a class="field-link" href="#f-autobuild.popAbove" aria-label="Link to autobuild.popAbove">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>trade</code>, <code>academy</code>, <code>garrison</code></td></tr><tr><td><span id="f-autobuild.div" class="field-name"><code>autobuild.div</code></span><a class="field-link" href="#f-autobuild.div" aria-label="Link to autobuild.div">#</a></td><td>integer &gt;= 1</td><td>no</td><td>in <code>trade</code>, <code>salvage</code></td></tr><tr><td><span id="f-autobuild.bonus" class="field-name"><code>autobuild.bonus</code></span><a class="field-link" href="#f-autobuild.bonus" aria-label="Link to autobuild.bonus">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>salvage</code></td></tr><tr><td><span id="f-autobuild.prodAbove" class="field-name"><code>autobuild.prodAbove</code></span><a class="field-link" href="#f-autobuild.prodAbove" aria-label="Link to autobuild.prodAbove">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>academy</code></td></tr><tr><td><span id="f-autobuild.offset" class="field-name"><code>autobuild.offset</code></span><a class="field-link" href="#f-autobuild.offset" aria-label="Link to autobuild.offset">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>academy</code></td></tr><tr><td><span id="f-autobuild.climates" class="field-name"><code>autobuild.climates</code></span><a class="field-link" href="#f-autobuild.climates" aria-label="Link to autobuild.climates">#</a></td><td>list of object (fields below)</td><td>no</td><td>in <code>terraform</code></td></tr><tr><td><span id="f-autobuild.neighbours" class="field-name"><code>autobuild.neighbours</code></span><a class="field-link" href="#f-autobuild.neighbours" aria-label="Link to autobuild.neighbours">#</a></td><td>object (fields below)</td><td>no</td><td>in <code>garrison</code>, <code>defence</code></td></tr><tr><td><span id="f-autobuild.unlessHas" class="field-name"><code>autobuild.unlessHas</code></span><a class="field-link" href="#f-autobuild.unlessHas" aria-label="Link to autobuild.unlessHas">#</a></td><td>snake_case key</td><td>no</td><td>in <code>garrison</code></td></tr><tr><td><span id="f-autobuild.govBonus" class="field-name"><code>autobuild.govBonus</code></span><a class="field-link" href="#f-autobuild.govBonus" aria-label="Link to autobuild.govBonus">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>garrison</code></td></tr><tr><td><span id="f-autobuild.conqueredBonus" class="field-name"><code>autobuild.conqueredBonus</code></span><a class="field-link" href="#f-autobuild.conqueredBonus" aria-label="Link to autobuild.conqueredBonus">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>garrison</code></td></tr><tr><td><span id="f-autobuild.interdictorBlocks" class="field-name"><code>autobuild.interdictorBlocks</code></span><a class="field-link" href="#f-autobuild.interdictorBlocks" aria-label="Link to autobuild.interdictorBlocks">#</a></td><td>true or false</td><td>no</td><td>in <code>defence</code></td></tr><tr><td><span id="f-autobuild.radiatedEco" class="field-name"><code>autobuild.radiatedEco</code></span><a class="field-link" href="#f-autobuild.radiatedEco" aria-label="Link to autobuild.radiatedEco">#</a></td><td>integer &gt;= 0</td><td>no</td><td>in <code>defence</code></td></tr><tr><td><span id="f-effects" class="field-name"><code>effects</code></span><a class="field-link" href="#f-effects" aria-label="Link to effects">#</a></td><td>list of effects (see effects.md)</td><td>no</td><td></td></tr></tbody></table><p>References to other records are written as keys; the game turns them into ids.</p><h2 id="also-register-it-in" tabindex="-1">Also register it in <a class="header-anchor" href="#also-register-it-in" aria-label="Permalink to &quot;Also register it in&quot;">​</a></h2><ul><li>governor-policies <code>defence</code> and <code>food</code> lists, if the colony governor should build it (<code>stages</code> is a keyed array: <code>stages.&lt;key&gt;.defence</code>)</li><li>start-state <code>buildings.priority</code> (the build order the start rules use)</li></ul><h2 id="computer-players" tabindex="-1">Computer players <a class="header-anchor" href="#computer-players" aria-label="Permalink to &quot;Computer players&quot;">​</a></h2><p>The empire AI and Auto Build weigh every building by its <code>autobuild</code> block: one of the closed set of weight formulas, with its parameters. <code>{ &quot;kind&quot;: &quot;flat&quot;, &quot;w&quot;: 0 }</code> means the AI never builds it; copy the block of the base building closest to yours to have it built like that one. The colony governor builds it only when a governor policy lists it. Strategic (auto-resolve) combat ignores new defence buildings.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Effects come from the closed effect list (see effects.md).</li><li><code>autobuild</code> takes one of the existing formulas; a new formula needs code.</li><li>A role that one building holds (for example the cloning building) has one holder; a mod can move the role, not add a second holder.</li></ul><h2 id="patch-paths" tabindex="-1">Patch paths <a class="header-anchor" href="#patch-paths" aria-label="Permalink to &quot;Patch paths&quot;">​</a></h2><p>Rows on this catalog address a record by <code>key</code> and a field by <code>path</code>:</p><ul><li><code>set</code>: <code>application</code>, <code>autobuild</code>, <code>autobuild.base</code>, <code>autobuild.bonus</code>, <code>autobuild.byFood</code>, <code>autobuild.climates</code>, <code>autobuild.conqueredBonus</code>, <code>autobuild.deficit</code>, <code>autobuild.div</code>, <code>autobuild.eco</code>, <code>autobuild.govBonus</code>, <code>autobuild.ind</code>, <code>autobuild.interdictorBlocks</code>, <code>autobuild.kind</code>, <code>autobuild.needsFarming</code>, <code>autobuild.neighbours</code>, <code>autobuild.neighbours.cp</code>, <code>autobuild.neighbours.n</code>, <code>autobuild.neighbours.p</code>, <code>autobuild.neighbours.th</code>, <code>autobuild.neighbours.w</code>, <code>autobuild.neighbours.x</code>, <code>autobuild.offset</code>, <code>autobuild.pop</code>, <code>autobuild.popAbove</code>, <code>autobuild.prodAbove</code>, <code>autobuild.radiatedEco</code>, <code>autobuild.rows</code>, <code>autobuild.skipFocus</code>, <code>autobuild.surplus</code>, <code>autobuild.tech</code>, <code>autobuild.treasuryDiv</code>, <code>autobuild.unlessHas</code>, <code>autobuild.w</code>, <code>buildable</code>, <code>cost</code>, <code>effects</code>, <code>hull</code>, <code>nameKey</code>, <code>upkeep</code></li><li><code>append</code>, <code>insertAfter</code>, <code>removeValue</code>: <code>autobuild.climates</code>, <code>autobuild.rows</code>, <code>effects</code></li></ul>',16)])])}const p=e(i,[["render",l]]);export{b as __pageData,p as default};
